// Extract JavaScript URLs - passive, exact-host allowlist (NGP-059)
const TAG = 'NGP-059';
const BASE = String($('Target Config').first().json.targetUrl || '').trim();
// URL global is unavailable in the Code node sandbox, so parse manually
function parseUrl(s) {
  const m = /^(https?:)[/][/]([^/?#]*)([^?#]*)(\?[^#]*)?/i.exec(s);
  if (!m) return null;
  let host = m[2]; let username = '';
  const at = host.lastIndexOf('@');
  if (at !== -1) { username = host.slice(0, at); host = host.slice(at + 1); }
  let port = '';
  const pm = /:([0-9]*)$/.exec(host);
  if (pm) { port = pm[1]; host = host.slice(0, pm.index); }
  const protocol = m[1].toLowerCase();
  if ((protocol === 'http:' && port === '80') || (protocol === 'https:' && port === '443')) port = '';
  return { protocol, hostname: host.toLowerCase(), port, username, path: m[3] || '/', query: m[4] || '' };
}
function normPath(p) {
  const out = [];
  for (const seg of p.split('/')) {
    if (seg === '..') { if (out.length > 1) out.pop(); }
    else if (seg !== '.') out.push(seg);
  }
  return out.join('/') || '/';
}
function resolveUrl(raw, b) {
  raw = raw.split('#')[0];
  let abs;
  if (/^[a-z][a-z0-9+.-]*:/i.test(raw)) {
    if (!/^https?:/i.test(raw)) return { protocol: raw.slice(0, raw.indexOf(':') + 1).toLowerCase(), hostname: '', port: '', username: '' };
    abs = raw;
  } else if (raw.startsWith('//')) {
    abs = b.protocol + raw;
  } else {
    const origin = b.protocol + '//' + (b.username ? b.username + '@' : '') + b.hostname + (b.port ? ':' + b.port : '');
    let rest = raw;
    let q = '';
    const qi = rest.indexOf('?');
    if (qi !== -1) { q = rest.slice(qi); rest = rest.slice(0, qi); }
    let path;
    if (rest === '') { path = b.path; if (!q) q = b.query; }
    else if (rest.startsWith('/')) path = rest;
    else path = b.path.slice(0, b.path.lastIndexOf('/') + 1) + rest;
    abs = origin + normPath(path) + q;
  }
  const u = parseUrl(abs);
  if (!u) return null;
  u.path = normPath(u.path);
  u.href = u.protocol + '//' + (u.username ? u.username + '@' : '') + u.hostname + (u.port ? ':' + u.port : '') + u.path + u.query;
  return u;
}
const _t = parseUrl(BASE);
if (!_t) throw new Error('targetUrl must be an absolute http(s) URL');
if (_t.protocol !== 'http:' && _t.protocol !== 'https:') throw new Error('targetUrl must be http(s)');
const ALLOWED_HOST = _t.hostname.toLowerCase();   // exact-host allowlist, derived from the single configured target
const MAX_FILES = 20;
const MAX_HTML_CHARS = 2000000;

const res = $input.first().json || {};
const status = Number(res.statusCode || 0);
let html = typeof res.body === 'string' ? res.body : (typeof res.data === 'string' ? res.data : '');

const stop = (reason, homepageFailed) => [{ json: { skip: true, homepageFailed, reason, tag: TAG } }];

if (res.error) {
  const msg = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
  return stop('Homepage request failed: ' + String(msg).slice(0, 200), true);
}
if (status >= 300) return stop('Homepage returned HTTP ' + status + ' (redirects are not followed)', true);
if (!html.trim()) return stop('Homepage response was empty', true);
if (html.length > MAX_HTML_CHARS) html = html.slice(0, MAX_HTML_CHARS);

const scriptRe = /<script\b[^>]*?\ssrc\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/gi;
const seen = new Set();
const approved = [];
const rejected = [];
let overLimit = 0;

for (const m of html.matchAll(scriptRe)) {
  const raw = (m[1] ?? m[2] ?? m[3] ?? '').trim();
  if (!raw) { rejected.push({ src: '(empty)', why: 'empty src' }); continue; }
  const u = resolveUrl(raw, _t);
  if (!u) { rejected.push({ src: raw.slice(0, 120), why: 'invalid URL' }); continue; }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') { rejected.push({ src: raw.slice(0, 120), why: 'unsupported scheme' }); continue; }
  if (u.hostname.toLowerCase() !== ALLOWED_HOST) { rejected.push({ src: raw.slice(0, 120), why: 'host not allowed' }); continue; }
  if (u.username || u.password) { rejected.push({ src: raw.slice(0, 120), why: 'credentials in URL' }); continue; }
  if (u.port) { rejected.push({ src: raw.slice(0, 120), why: 'non-default port' }); continue; }
  const href = u.href;
  if (seen.has(href)) continue;
  seen.add(href);
  if (approved.length >= MAX_FILES) { overLimit++; continue; }
  approved.push(href);
}

if (approved.length === 0) {
  return [{ json: { skip: true, homepageFailed: false, reason: 'No approved external <script src> URLs found on the homepage', rejected, overLimit, tag: TAG } }];
}

return approved.map((url, i) => ({
  json: { url, tag: TAG, ...(i === 0 ? { rejected, overLimit } : {}) }
}));

// Detect Candidate Secrets - passive regex matching, masked output only (NGP-059)
const TAG = 'NGP-059';
const BASE = String($('Target Config').first().json.targetUrl || '').trim();
const TARGET = String((/^https?:[/][/](?:[^/?#@]*@)?([^/?#:]*)/i.exec(BASE) || [])[1] || '').toLowerCase();
const MAX_CHARS = 500000;     // per-file scan cap
const MAX_FINDINGS = 50;      // per-scan cap

const extractItems = $('Extract JavaScript URLs').all();
const meta = (extractItems[0] && extractItems[0].json) || {};
const urlList = extractItems.map(i => i.json.url);

const PATTERNS = [
  { type: 'api_key',  re: /\b(api[_-]key)["']?\s*[:=]\s*["']([^"'\s]{4,})["']/gi, vg: 2, named: true },
  { type: 'token',    re: /\b(access_token|auth_token|token)["']?\s*[:=]\s*["']([^"'\s]{4,})["']/gi, vg: 2, named: true },
  { type: 'secret',   re: /\b(client_secret|secret_key|secret)["']?\s*[:=]\s*["']([^"'\s]{4,})["']/gi, vg: 2, named: true },
  { type: 'aws_access_key_id', re: /\b((?:AKIA|ASIA)[A-Z0-9]{16})\b/g, vg: 1, named: false },
];

const mask = v => String(v).slice(0, 3) + '***';
const PLACEHOLDER = /^(x+|\*+|\.+|-+|_+|your[\w\-.]*|<.*>|\{\{.*\}\}|\$\{.*\}|example\w*|test\w*|changeme|password|null|undefined|dummy\w*|sample\w*|todo|none|string|value)$/i;

function entropy(s) {
  const freq = {};
  for (const ch of s) freq[ch] = (freq[ch] || 0) + 1;
  let h = 0;
  for (const k in freq) { const p = freq[k] / s.length; h -= p * Math.log2(p); }
  return h;
}
function charset(s) {
  if (/^[0-9a-f]+$/i.test(s)) return 'hex';
  if (/^[A-Z0-9]+$/.test(s)) return 'uppercase-alphanumeric';
  if (/^[A-Za-z0-9]+$/.test(s)) return 'alphanumeric';
  if (/^[A-Za-z0-9+/=_-]+$/.test(s)) return 'base64-like';
  return 'mixed';
}
function lineAt(body, idx) {
  let n = 1;
  for (let i = body.indexOf('\n'); i !== -1 && i < idx; i = body.indexOf('\n', i + 1)) n++;
  return n;
}
function srcIndex(item, fallback) {
  const p = item.pairedItem;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p[0] && typeof p[0].item === 'number') return p[0].item;
  return fallback;
}

const failures = [];
const findings = [];
const seenKeys = new Set();
let fetchedOk = 0;
let truncatedFiles = 0;
let findingsTruncated = false;
const approvedCount = meta.skip ? 0 : urlList.length;

if (meta.homepageFailed) failures.push({ url: BASE, reason: meta.reason });

if (!meta.skip) {
  const inputs = $input.all();
  inputs.forEach((item, i) => {
    const j = item.json || {};
    const url = urlList[srcIndex(item, i)] || '(unknown URL)';
    if (j.error) {
      const msg = typeof j.error === 'string' ? j.error : (j.error.message || 'request error');
      failures.push({ url, reason: String(msg).slice(0, 160) });
      return;
    }
    const status = Number(j.statusCode || 0);
    if (status >= 300) { failures.push({ url, reason: 'HTTP ' + status + (status < 400 ? ' (redirect not followed)' : '') }); return; }
    let body = typeof j.body === 'string' ? j.body : (typeof j.data === 'string' ? j.data : '');
    if (!body.trim()) { failures.push({ url, reason: 'empty response' }); return; }
    fetchedOk++;
    if (body.length > MAX_CHARS) { body = body.slice(0, MAX_CHARS); truncatedFiles++; }

    for (const p of PATTERNS) {
      for (const m of body.matchAll(p.re)) {
        if (findings.length >= MAX_FINDINGS) { findingsTruncated = true; break; }
        const value = m[p.vg];           // raw value: used locally only, never stored or output
        const keyName = p.named ? m[1].toLowerCase() : p.type;
        const line = lineAt(body, m.index);
        const masked = mask(value);
        const key = [keyName, url, line, masked].join('|');
        if (seenKeys.has(key)) continue;
        seenKeys.add(key);
        findings.push({
          id: 'F' + String(findings.length + 1).padStart(3, '0'),
          tag: TAG,
          patternType: keyName,
          maskedValue: masked,
          sourceUrl: url,
          lineNumber: line,
          evidence: 'matched key "' + keyName + '"; value length ' + value.length +
            '; charset ' + charset(value) + '; entropy ' + entropy(value).toFixed(1) +
            ' bits/char; placeholder-like: ' + (PLACEHOLDER.test(value) ? 'yes' : 'no')
        });
      }
    }
  });
}

return [{ json: {
  tag: TAG,
  target: TARGET,
  skippedReason: meta.skip ? meta.reason : null,
  homepageFailed: !!meta.homepageFailed,
  approvedCount,
  fetchedOk,
  failedCount: failures.length,
  failures,
  rejectedCount: (meta.rejected || []).length,
  overLimit: meta.overLimit || 0,
  truncatedFiles,
  findingsTruncated,
  findingsCount: findings.length,
  findings
} }];

