// Format Telegram Messages - merges AI classifications, never handles raw secrets (NGP-059)
const TAG = 'NGP-059';
const scan = $('Detect Candidate Secrets').first().json;
const CLASSES = ['LIKELY_SECRET', 'LIKELY_FALSE_POSITIVE', 'NEEDS_REVIEW'];
const CONF = ['LOW', 'MEDIUM', 'HIGH'];
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let results = [];
try {
  const out = $input.first().json.output;
  if (out && Array.isArray(out.results)) results = out.results;
} catch (e) { /* no AI output; fall back to NEEDS_REVIEW */ }
const byId = {};
for (const r of results) if (r && r.id) byId[r.id] = r;

const merged = (scan.findings || []).map(f => {
  const r = byId[f.id] || {};
  const classification = CLASSES.includes(r.classification) ? r.classification : 'NEEDS_REVIEW';
  const confidence = CONF.includes(String(r.confidence).toUpperCase()) ? String(r.confidence).toUpperCase() : 'LOW';
  const rationale = r.rationale ? String(r.rationale).slice(0, 240) : 'No AI classification returned; manual review needed.';
  return { ...f, classification, confidence, rationale };
});

const count = c => merged.filter(m => m.classification === c).length;

const chunk = (blocks, sep) => {
  const out = []; let cur = '';
  for (const b of blocks) {
    if (cur && (cur.length + sep.length + b.length) > 3800) { out.push(cur); cur = b; }
    else cur = cur ? cur + sep + b : b;
  }
  if (cur) out.push(cur);
  return out;
};

const messages = [];

// 1) Summary
let s = '<b>Passive JS Secret Scanner</b>\nTag: ' + TAG + '\nTarget: ' + esc(scan.target) + '\n\n';
s += 'JS files approved: ' + scan.approvedCount + '\nFetched OK: ' + scan.fetchedOk + '\nFailed requests: ' + scan.failedCount + '\n';
if (scan.rejectedCount) s += 'Rejected script URLs (host/scheme rules): ' + scan.rejectedCount + '\n';
if (scan.overLimit) s += 'Skipped (over file limit): ' + scan.overLimit + '\n';
if (scan.skippedReason) s += 'Note: ' + esc(scan.skippedReason) + '\n';
s += '\n';
if (merged.length === 0) {
  s += 'No candidate secrets detected.';
} else {
  s += 'Candidate findings: ' + merged.length + '\nLIKELY_SECRET: ' + count('LIKELY_SECRET') +
       '\nNEEDS_REVIEW: ' + count('NEEDS_REVIEW') + '\nLIKELY_FALSE_POSITIVE: ' + count('LIKELY_FALSE_POSITIVE') +
       '\n\nAll matches are potential findings, not confirmed credentials.';
  if (scan.findingsTruncated) s += '\n(Finding cap reached; results truncated.)';
}
messages.push(s);

// 2) Findings
const blocks = merged.map(m =>
  '<b>' + m.classification + '</b>\nTag: ' + TAG +
  '\nPattern: ' + esc(m.patternType) +
  '\nMasked value: <code>' + esc(m.maskedValue) + '</code>' +
  '\nSource: ' + esc(m.sourceUrl) +
  '\nLine: ' + m.lineNumber +
  '\nConfidence: ' + m.confidence +
  '\nRationale: ' + esc(m.rationale));
for (const c of chunk(blocks, '\n\n')) messages.push(c);

// 3) Failed requests, reported separately
if (scan.failures && scan.failures.length) {
  const lines = scan.failures.slice(0, 30).map(f => '- ' + esc(f.url) + ' : ' + esc(f.reason));
  for (const c of chunk(lines, '\n')) messages.push('<b>Failed requests</b> (Tag: ' + TAG + ')\n' + c);
}

return messages.map(text => ({ json: { tag: TAG, text } }));
